//! Static description of the pf_active data dictionary, used to build and resolve paths.
//!
//! **WARNING** This file is autogenerated by `rust/imas_rs/imas_updater/build_ids.py`.
//! Any changes will be overwritten.
//!
//! Each leaf carries the function that reads it out of the IDS, so the path a
//! reader follows is written once and checked by the compiler. The `read` closures
//! capture nothing, so they coerce to plain `fn` pointers and the whole description
//! stays a `static`.

#![allow(clippy::all)]

use super::{IndexSpec, Leaf, Node, NodeKind, gather, no_levels};
use crate::dd_base_types::{FLT_0D, FLT_1D, FLT_2D, INT_0D, INT_1D, INT_2D, STR_0D};
use crate::ids::pf_active::PfActive;
use std::any::Any;

// ============================================================================
// Array-of-structures lengths
// ============================================================================

/// Length of each array-of-structures level along `circuit`.
fn lengths_circuit(pf_active: &PfActive, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_active.circuit.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `code_library`.
fn lengths_code_library(pf_active: &PfActive, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_active.code.library.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `coil`.
fn lengths_coil(pf_active: &PfActive, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_active.coil.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `coil_element`.
fn lengths_coil_element(pf_active: &PfActive, level: usize, at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_active.coil.len()),
        1 => return Some(pf_active.coil[at[0]].element.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `coil_function`.
fn lengths_coil_function(pf_active: &PfActive, level: usize, at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_active.coil.len()),
        1 => return Some(pf_active.coil[at[0]].function.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `supply`.
fn lengths_supply(pf_active: &PfActive, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(pf_active.supply.len()),
        _ => return None,
    }
}

